package com.castsprint.android.security

import android.net.Uri
import com.castsprint.android.protocol.ProtocolV1

/**
 * Encapsulates parameters required for secure LAN Wi-Fi pairing and TLS certificate pinning.
 *
 * Parameters:
 * - host: Local IP of the Windows receiver.
 * - port: Port of the receiver (default 27183).
 * - fingerprintSha256: SHA-256 fingerprint of the receiver's TLS certificate.
 * - sessionToken: Random connection-scoped secret generated by the receiver for authorization.
 * - receiverName: Friendly name of the desktop device.
 */
data class PairingInfo(
    val host: String,
    val port: Int = ProtocolV1.DEFAULT_PORT,
    val fingerprintSha256: String,
    val sessionToken: String,
    val receiverName: String = "Windows PC",
) {
    fun toUriString(): String {
        return Uri.Builder()
            .scheme("castsprint")
            .authority("connect")
            .appendQueryParameter("host", host)
            .appendQueryParameter("port", port.toString())
            .appendQueryParameter("fp", fingerprintSha256)
            .appendQueryParameter("token", sessionToken)
            .appendQueryParameter("name", receiverName)
            .build()
            .toString()
    }

    companion object {
        fun parse(input: String): PairingInfo? {
            val trimmed = input.trim()
            if (trimmed.isEmpty()) return null

            return try {
                if (trimmed.startsWith("castsprint://", ignoreCase = true)) {
                    val uri = Uri.parse(trimmed)
                    val host = uri.getQueryParameter("host") ?: return null
                    val port = uri.getQueryParameter("port")?.toIntOrNull() ?: ProtocolV1.DEFAULT_PORT
                    val fp = uri.getQueryParameter("fp") ?: ""
                    val token = uri.getQueryParameter("token") ?: ""
                    val name = uri.getQueryParameter("name") ?: "Windows PC"
                    PairingInfo(host, port, fp, token, name)
                } else if (trimmed.contains(",")) {
                    // CSV format: "host,port,fingerprint,token,name"
                    val parts = trimmed.split(",").map { it.trim() }
                    if (parts.size >= 4) {
                        val host = parts[0]
                        val port = parts[1].toIntOrNull() ?: ProtocolV1.DEFAULT_PORT
                        val fp = parts[2]
                        val token = parts[3]
                        val name = if (parts.size > 4) parts[4] else "Windows PC"
                        PairingInfo(host, port, fp, token, name)
                    } else null
                } else {
                    null
                }
            } catch (ignored: Exception) {
                null
            }
        }
    }
}
